WITH base AS (SELECT *, INITCAP(TRIM(status)) AS status_title, QUARTER(delivered_date) AS delivered_date_quarter, COALESCE(carrier, 'N/A') AS carrier_clean FROM shipments WHERE delivered_date >= DATE '2023-07-14' AND carrier IS NOT NULL), metrics AS (SELECT id, order_id, shipped_date, delivered_date, cost, status, status_title, delivered_date_quarter, LEAD(cost, 1) OVER (PARTITION BY MONTH(shipped_date), order_id ORDER BY shipped_date, id) AS next_cost, SUM(delivered_date_quarter) OVER (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_delivered_date_quarter FROM base WHERE carrier = 'FedEx'), with_windows AS (SELECT *, NTILE(3) OVER w_ordered AS cost_bucket, STDDEV_SAMP(delivered_date_quarter) OVER (PARTITION BY status, order_id) AS status_stddev_samp_delivered_date_quarter FROM metrics WINDOW w_ordered AS (PARTITION BY order_id ORDER BY cost DESC, id)), with_dims AS (SELECT s.*, d.shipping_fee, d.order_date FROM with_windows s JOIN orders d ON s.order_id = d.id), wide AS (SELECT * FROM (SELECT order_id, status, next_cost FROM with_dims) src PIVOT (MAX(next_cost) AS value_sum, COUNT(1) AS n FOR status IN ('DELIVERED' AS delivered, 'IN_TRANSIT' AS in_transit))) SELECT order_id, delivered_value_sum, in_transit_value_sum, in_transit_n FROM wide ORDER BY in_transit_n, delivered_value_sum;
